-- Seed: written lesson content for lessons the AI generator could not finish (provider daily quota).
-- Idempotent: only fills lessons whose explanation is still NULL.
update lessons set explanation = $j${"overview": "In this lesson you learn how to write a short paragraph that describes a place, such as your room, your home, or a favorite spot. After the lesson you will be able to write 4 to 6 clear sentences that help a reader picture the place.", "sections": [{"heading": "Start with a topic sentence", "body": "A paragraph about a place begins with one sentence that names the place and gives your main idea.\n- Say what the place is.\n- Add one word that shows how it looks or feels, like **small**, **cozy**, or **busy**.", "examples": [{"text": "My room is small but cozy.", "note": "names the place and gives the main idea"}, {"text": "My grandmother's kitchen is warm and bright.", "note": "place + two describing words"}, {"text": "The park near my house is quiet in the morning.", "note": "place + when it is like this"}]}, {"heading": "Add details with be and have", "body": "Use **is/are** to say what the place is like and **have/has** to say what it contains.\n- Use **There is** for one thing and **There are** for many things.\n- Use adjectives before nouns: a **big** desk.", "examples": [{"text": "I have a big desk for studying.", "note": "have + adjective + noun + purpose"}, {"text": "There are two windows in the room.", "note": "There are + plural noun"}, {"text": "The walls are light blue.", "note": "is/are + color"}]}, {"heading": "Say where things are", "body": "Prepositions of place help the reader see the room.\n- **next to**, **in front of**, **behind**, **on**, **under**, **between**\n- Put the preposition before the thing that gives the position.", "examples": [{"text": "My bed is next to the window.", "note": "next to = beside"}, {"text": "The lamp is on the desk.", "note": "on = on the surface"}, {"text": "There is a small garden behind the house.", "note": "behind = at the back"}]}, {"heading": "Finish with a closing sentence", "body": "End with one sentence about how you feel about the place. This makes the paragraph complete.", "examples": [{"text": "I love my room because it is my quiet place.", "note": "feeling + reason with because"}, {"text": "It is my favorite place to relax.", "note": "short, simple closing"}]}], "keyPoints": ["Begin with a topic sentence that names the place.", "Use adjectives to show size, color, and feeling.", "Use There is / There are and have / has to list what is in the place.", "Use prepositions like next to, on, and behind to show position.", "End with a sentence about how you feel.", "Start each sentence with a capital letter and end it with a full stop."], "commonMistakes": [{"wrong": "My room have a big window.", "right": "My room has a big window.", "why": "Use has with he, she, it, and singular nouns like room."}, {"wrong": "There is two chairs.", "right": "There are two chairs.", "why": "Use There are with plural nouns."}, {"wrong": "I have a desk big.", "right": "I have a big desk.", "why": "In English the adjective comes before the noun."}], "recap": "A good place paragraph has a topic sentence, details, positions, and a closing feeling. Now write your own paragraph about your home or favorite place."}$j$::jsonb where id='6829914e-367a-43f1-8b03-7aa3c53baa2a' and explanation is null;
update lessons set explanation = $j${"overview": "In this lesson you learn how to check a short paragraph and fix mistakes in capital letters, punctuation, and complete sentences. After the lesson you will be able to edit your own writing so it is clear and correct.", "sections": [{"heading": "Why editing matters", "body": "Editing is the last step of writing. You read your paragraph again and fix small mistakes so the reader understands it easily.\n- Read slowly, one sentence at a time.\n- Check capitals, punctuation, and complete sentences.", "examples": [{"text": "my house is big", "note": "needs a capital letter and a full stop"}, {"text": "My house is big.", "note": "correct sentence"}]}, {"heading": "Capital letters", "body": "Use a capital letter in these places:\n- at the start of every sentence\n- for the word **I**\n- for names of people, cities, and countries", "examples": [{"text": "My sister lives in Cairo.", "note": "capital for the sentence start and the city name"}, {"text": "Today I am at home.", "note": "I is always a capital letter"}]}, {"heading": "End punctuation", "body": "Every sentence needs punctuation at the end.\n- Use a full stop (.) for a normal statement.\n- Use a question mark (?) for a question.\n- Do not join two sentences with no punctuation between them.", "examples": [{"text": "It has a garden.", "note": "statement ends with a full stop"}, {"text": "Do you like gardens?", "note": "question ends with a question mark"}]}, {"heading": "Fix a real paragraph", "body": "Look at this text: my house is big it has a garden the garden is green.\n1. Find where each idea ends.\n2. Add a full stop there.\n3. Change the first letter of each sentence to a capital.", "examples": [{"text": "My house is big. It has a garden. The garden is green.", "note": "three complete sentences, correctly edited"}]}], "keyPoints": ["Editing means reading again and fixing small mistakes.", "Start every sentence with a capital letter.", "Always write I as a capital letter.", "End every sentence with . or ?", "Do not put two sentences together without punctuation.", "Read the paragraph one more time after you fix it."], "commonMistakes": [{"wrong": "my house is big it has a garden", "right": "My house is big. It has a garden.", "why": "Two ideas need two sentences, each with a capital and a full stop."}, {"wrong": "Yesterday i went to the park.", "right": "Yesterday I went to the park.", "why": "The word I is always a capital letter."}, {"wrong": "Do you like tea.", "right": "Do you like tea?", "why": "A question ends with a question mark."}], "recap": "Check capitals, end punctuation, and complete sentences every time. Now practice by fixing the paragraph in the exercise."}$j$::jsonb where id='1cc66798-893b-4ef7-94a4-262256f250b9' and explanation is null;
update lessons set explanation = $j${"overview": "In this lesson you put linking words together to write one smooth paragraph. After the lesson you will be able to use words like also, however, and as a result to connect your ideas clearly.", "sections": [{"heading": "Why linking words help", "body": "Linking words show how one idea connects to the next. Without them, a paragraph sounds like a list of separate sentences.\n- They make your writing flow.\n- They help the reader follow your thinking.", "examples": [{"text": "I like weekends. I rest at home.", "note": "correct, but the ideas feel separate"}, {"text": "I like weekends because I can rest at home.", "note": "because links the reason"}]}, {"heading": "Adding and contrasting", "body": "Use **also** to add an idea and **however** to show a different or opposite idea.\n- Put **also** before the main verb: I also visit friends.\n- Put **However,** at the start of a new sentence with a comma.", "examples": [{"text": "I also visit my friends on Saturday.", "note": "also adds another activity"}, {"text": "I want to go out. However, it is raining.", "note": "however shows contrast"}]}, {"heading": "Showing a result", "body": "Use **as a result** to show what happened because of something before it.\n- Put a comma after it.\n- The sentence after it tells the result.", "examples": [{"text": "I slept late. As a result, I felt fresh.", "note": "result of sleeping late"}, {"text": "It rained all day. As a result, we stayed home.", "note": "cause then result"}]}, {"heading": "Build your final paragraph", "body": "Follow this plan for a paragraph about your ideal weekend:\n1. Start with a topic sentence.\n2. Add two or three activities, using **also**.\n3. Add one problem or contrast with **however**.\n4. Finish with a result using **as a result**.", "examples": [{"text": "My ideal weekend is relaxing. I sleep late, and I also cook a big breakfast. However, I do not like staying inside all day. As a result, I walk in the park every afternoon.", "note": "topic, also, however, as a result"}]}], "keyPoints": ["Linking words connect ideas so the paragraph flows.", "Use also to add information.", "Use However, to show contrast, with a comma after it.", "Use As a result, to show an effect, with a comma after it.", "Do not use too many linking words in one paragraph.", "Read your paragraph aloud to check that it sounds smooth."], "commonMistakes": [{"wrong": "However I was tired.", "right": "However, I was tired.", "why": "Put a comma after however at the start of a sentence."}, {"wrong": "I am busy, also I am tired.", "right": "I am busy. I am also tired.", "why": "Also usually goes before the main verb or after am/is/are."}, {"wrong": "As a result of I was late.", "right": "As a result, I missed the bus.", "why": "As a result is followed by a comma and a complete sentence."}], "recap": "Use also, however, and as a result to join your ideas in order. Now write your ideal weekend paragraph with all three."}$j$::jsonb where id='123366f7-1ee0-47d6-9a5c-ef46782fbe4f' and explanation is null;
